#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


run_wizard() {

TOTAL_STAGES=6

# Run from anywhere: work in this checkout (gh secret set targets its repo),
# but keep local secrets in the main checkout's .env, which config.py loads.
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"
MAIN_ROOT="$(dirname "$(git rev-parse --path-format=absolute --git-common-dir)")"
ENV_FILE="$MAIN_ROOT/.env"
PY="$REPO_ROOT/.venv/bin/python"
[[ -x "$PY" ]] || PY="python3"

banner "Cloudflare R2 · durable DB seed"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Turn on R2"
say "R2 is Cloudflare's file storage. The daily build will save its verified"
say "database there and start the next day from it. Free up to 10 GB."
open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
step "Log in as philip.bergman6@gmail.com if asked, and pick your account."
step "If you see 'Purchase R2 Plan' / 'Get started': click it. The plan is \$0;"
step "it may ask you to confirm the Visa already on the account."
note "Labels in Cloudflare's UI shift over time; the R2 page is under"
note "Storage & Databases → R2 Object Storage in the left sidebar."
pause "Press Enter once the R2 overview page shows (it lists buckets, maybe none)."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create the bucket"
step "Click 'Create bucket'."
step "Name: mirror-market-db   Location: Automatic   Storage class: Standard."
step "Click 'Create bucket'. Leave Public Access OFF (the default) — the DB is private."
ask R2_BUCKET "Bucket name you created (type mirror-market-db):"
while [[ ! "$R2_BUCKET" =~ ^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$ ]]; do
  warn "R2 bucket names are 3–63 lowercase letters, digits and hyphens."
  ask R2_BUCKET "Bucket name:"
done

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Copy your Account ID"
step "Go back to the R2 overview page."
step "On the right, under 'Account Details', copy the Account ID (32 hex characters)."
note "It is also the long hex segment in the dashboard URL: dash.cloudflare.com/<account id>/r2/..."
ask R2_ACCOUNT_ID "Paste the Account ID:"
while [[ ! "$R2_ACCOUNT_ID" =~ ^[0-9a-f]{32}$ ]]; do
  warn "That isn't 32 lowercase hex characters."
  ask R2_ACCOUNT_ID "Paste the Account ID:"
done

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Create an API token for this bucket only"
step "On the R2 overview page click 'Manage API tokens' (right side, under Account Details)."
step "Click 'Create API token' (an Account API token is fine)."
step "Name: mirror-market-ci"
step "Permissions: 'Object Read & Write'."
step "Specify bucket(s): 'Apply to specific buckets only' → select $R2_BUCKET."
step "TTL: Forever. Leave IP filtering empty (GitHub runners have no fixed IP)."
step "Click 'Create API Token'. The next page shows the keys ONCE — keep it open."
pause "Press Enter when the page with the Access Key ID and Secret Access Key is showing."
ask R2_ACCESS_KEY_ID "Paste the Access Key ID (32 hex):"
while [[ ! "$R2_ACCESS_KEY_ID" =~ ^[0-9a-f]{32}$ ]]; do
  warn "Expected 32 hex characters — copy the 'Access Key ID', not the token value."
  ask R2_ACCESS_KEY_ID "Paste the Access Key ID:"
done
ask_secret R2_SECRET_ACCESS_KEY "Paste the Secret Access Key (hidden, 64 hex):"
while [[ ! "$R2_SECRET_ACCESS_KEY" =~ ^[0-9a-f]{64}$ ]]; do
  warn "Expected 64 hex characters — copy the 'Secret Access Key'."
  ask_secret R2_SECRET_ACCESS_KEY "Paste the Secret Access Key:"
done
write_env R2_BUCKET "$R2_BUCKET"
write_env R2_ACCOUNT_ID "$R2_ACCOUNT_ID"
write_env R2_ACCESS_KEY_ID "$R2_ACCESS_KEY_ID"
write_env R2_SECRET_ACCESS_KEY "$R2_SECRET_ACCESS_KEY"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Check the keys work"
say "Uploads a tiny probe file to wizard-check/probe.bin, reads it back, deletes it."
say "It never touches verified/latest.db.gz, so the daily build's seed is safe."
if R2_ACCOUNT_ID="$R2_ACCOUNT_ID" R2_ACCESS_KEY_ID="$R2_ACCESS_KEY_ID" \
   R2_SECRET_ACCESS_KEY="$R2_SECRET_ACCESS_KEY" R2_BUCKET="$R2_BUCKET" \
   "$PY" - <<'PY'
import os, sys, tempfile
from pathlib import Path
sys.path.insert(0, os.getcwd())
from pipeline.db_snapshot import R2Store, config_from_env
cfg = config_from_env()
store = R2Store(cfg)
with tempfile.TemporaryDirectory() as tmp:
    src, back = Path(tmp) / "probe.bin", Path(tmp) / "back.bin"
    src.write_bytes(os.urandom(256))
    store.put("wizard-check/probe.bin", src, {"sha256": "probe"})
    meta = store.get("wizard-check/probe.bin", back)
    assert meta is not None and back.read_bytes() == src.read_bytes(), "read-back mismatch"
    store._client.delete_object(Bucket=cfg.bucket, Key="wizard-check/probe.bin")
print("  probe round-trip OK")
PY
then
  say "R2 accepts the token: write, read and delete all work."
else
  warn "The probe failed — the error is printed above."
  warn "Usual causes: token scoped to a different bucket, or 'Object Read only'."
  confirm "Set the GitHub secrets anyway?" || { SKIPPED+=("GitHub secrets (probe failed; fix the token and re-run)"); finish; return; }
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Give the keys to GitHub Actions"
say "Sets four repo secrets on $(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || echo 'this repo')."
say "deploy-dashboard.yml reads exactly these names."
if confirm "Set R2_ACCOUNT_ID, R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY, R2_BUCKET now?"; then
  set_secret R2_ACCOUNT_ID "$R2_ACCOUNT_ID"
  set_secret R2_ACCESS_KEY_ID "$R2_ACCESS_KEY_ID"
  set_secret R2_SECRET_ACCESS_KEY "$R2_SECRET_ACCESS_KEY"
  set_secret R2_BUCKET "$R2_BUCKET"
else
  SKIPPED+=("GitHub secrets R2_* (re-run this wizard to set them)")
fi
note "The first green daily build after the PR merges saves the first seed;"
note "the one after that starts from it. Both say so on the run page."
pause

finish
}

run_wizard "$@"; exit
